describe("numbers match the old game's filters, minus trailing zeros", () => {
  it.each(OLD)("%s %s", (notation, value, num, long, num2, long2) => {
    const f = createFormatter({ notation });
    const v = new Decimal(value);
    expect(f.num(v)).toBe(trimZeros(num));
    expect(f.long(v)).toBe(trimZeros(long));
    expect(f.num(v, 2)).toBe(trimZeros(num2));
    expect(f.long(v, 2)).toBe(trimZeros(long2));
  });
});

describe("trimZeros", () => {
  it.each([
    ["8.00000 million", "8 million"],
    ["1.00M", "1M"],
    ["1.50B", "1.5B"],
    ["123.456 thousand", "123.456 thousand"],
    ["100.000 thousand", "100 thousand"],
    ["1.00000e300", "1e300"],
    ["15.0E9999", "15E9999"],
    ["0.00", "0"],
    ["12,345", "12,345"],
    ["35", "35"],
  ])("%s -> %s", (input, out) => {
    expect(trimZeros(input)).toBe(out);
  });
});
